var vonage_default = "---\nlayout: article\ntitle: Vonage\ndescription: Send SMS messages to your Appwrite users using Vonage and Appwrite Messaging.\nback: /docs/\n---\n\nVonage lets you send customized SMS messages to your users.\nThese SMS messages can be sent immediately or scheduled.\nYou can send SMS messages for purposes like reminders, promotions, announcements, and even custom authentication flows.\n\n{% section #add-provider step=1 title=\"Add provider\" %}\n\nTo add Vonage as a provider, navigate to **Messaging** > **Providers** > {% icon icon=\"plus\" size=\"m\" /%} **Add provider** > **SMS**.\n{% only_dark %}\n![Add a Vonage provider](/images/docs/messaging/providers/vonage/dark/provider.avif)\n{% /only_dark %}\n{% only_light %}\n![Add a Vonage provider](/images/docs/messaging/providers/vonage/provider.avif)\n{% /only_light %}\n\nGive your provider a name > choose **Vonage** > click **Save and continue**.\nThe provider will be saved to your project, but not enabled until you complete its configuration.\n{% /section %}\n{% section #configure-provider step=2 title=\"Configure provider\" %}\n\nIn the **Configure** step, you will need to provide details from your Vonage dashboard to connect your Appwrite project.\n\nYou will need to provide the following information from your **Vonage dashboard**.\n\n{% table %}\n* Field name\n*\n---\n* API key\n* Head to Vonage dashboard > **Build & manage** > **API settings** and copy the API key.\n---\n* API secret\n* Head to Vonage dashboard > **Build & manage** > **API settings** and copy the API secret.\n---\n* Sender number\n* You can access your numbers by navigating to Vonage dashboard > **Build & manage** > **Numbers** > **Your numbers**.\n---\n{% /table %}\n\nAfter adding the following details, click **Save and continue** to enable the provider.\n{% /section %}\n\n{% section #test-provider step=3 title=\"Test provider\" %}\nBefore sending your first message,\nmake sure you've configured [a topic](/docs/products/messaging/topics) and [a target](/docs/products/messaging/targets) to send messages to.\n{% tabs %}\n{% tabsitem #console title=\"Console\" %}\nTo send a test message, navigate to **Messaging** > **Messages** > {% icon icon=\"plus\" size=\"m\" /%} **Create message** > **SMS**.\n{% only_dark %}\n![Create an SMS message](/images/docs/messaging/messages/dark/create-sms-message.avif)\n{% /only_dark %}\n{% only_light %}\n![Create an SMS message](/images/docs/messaging/messages/create-sms-message.avif)\n{% /only_light %}\n\nAdd your message and in the targets step, select one of your test targets. Set the schedule to **Now** and click **Send**.\n\nVerify that you can receive the message in your inbox. If not, check for logs in the Appwrite Console or in your provider's logs.\n{% /tabsitem %}\n\n{% tabsitem #server-sdk title=\"Server SDK\" %}\nTo send a message programmatically, use an [Appwrite Server SDK](/docs/sdks#server).\n{% multicode %}\n```server-nodejs\nconst sdk = require('node-appwrite');\n\n// Init SDK\nconst client = new sdk.Client();\n\nconst messaging = new sdk.Messaging(client);\n\nclient\n    .setEndpoint('https://<REGION>.cloud.appwrite.io/v1') // Your API Endpoint\n    .setProject('<PROJECT_ID>')                 // Your project ID\n    .setKey('919c2d18fb5d4...a2ae413da83346ad2') // Your secret API key\n;\n\nconst message = await messaging.createSms({\n    messageId: '<MESSAGE_ID>',\n    content: '<CONTENT>',\n    topics: [],\n    users: [],\n    targets: [],\n    draft: true,\n    scheduledAt: ''\n});\n```\n```deno\nimport * as sdk from \"npm:node-appwrite\";\n\n// Init SDK\nlet client = new sdk.Client();\n\nlet messaging = new sdk.Messaging(client);\n\nclient\n    .setEndpoint('https://<REGION>.cloud.appwrite.io/v1') // Your API Endpoint\n    .setProject('<PROJECT_ID>')                 // Your project ID\n    .setKey('919c2d18fb5d4...a2ae413da83346ad2') // Your secret API key\n;\n\nconst message = await messaging.createSms({\n    messageId: '<MESSAGE_ID>',\n    content: '<CONTENT>',\n    topics: [],\n    users: [],\n    targets: [],\n    draft: true,\n    scheduledAt: ''\n});\n```\n```php\n<?php\n\nuse Appwrite\\Client;\nuse Appwrite\\Services\\Messaging;\n\n$client = new Client();\n\n$client\n    ->setEndpoint('https://<REGION>.cloud.appwrite.io/v1') // Your API Endpoint\n    ->setProject('<PROJECT_ID>')                 // Your project ID\n    ->setKey('919c2d18fb5d4...a2ae413da83346ad2') // Your secret API key\n;\n\n$messaging = new Messaging($client);\n\n$result = $messaging->createSms(\n    messageId: '<MESSAGE_ID>',\n    content: '<CONTENT>',\n    topics: [],                                   // optional\n    users: [],                                    // optional\n    targets: [],                                  // optional\n    draft: true,                                  // optional\n    scheduledAt: ''                               // optional\n);\n```\n```python\nfrom appwrite.client import Client\nfrom appwrite.services.messaging import Messaging\n\nclient = Client()\n\n(client\n  .set_endpoint('https://<REGION>.cloud.appwrite.io/v1') # Your API Endpoint\n  .set_project('<PROJECT_ID>')                 # Your project ID\n  .set_key('919c2d18fb5d4...a2ae413da83346ad2') # Your secret API key\n)\n\nmessaging = Messaging(client)\n\nresult = messaging.create_sms(\n    message_id = '<MESSAGE_ID>',\n    content = '<CONTENT>',\n    topics = [],                                # optional\n    users = [],                                 # optional\n    targets = [],                               # optional\n    draft = True,                               # optional\n    scheduled_at = ''                           # optional\n)\n```\n```ruby\nrequire 'appwrite'\n\ninclude Appwrite\n\nclient = Client.new\n    .set_endpoint('https://<REGION>.cloud.appwrite.io/v1') # Your API Endpoint\n    .set_project('<PROJECT_ID>')                 # Your project ID\n    .set_key('919c2d18fb5d4...a2ae413da83346ad2') # Your secret API key\n\nmessaging = Messaging.new(client)\n\nresponse = messaging.create_sms(\n    message_id: '<MESSAGE_ID>',\n    content: '<CONTENT>',\n    topics: [],                                   # optional\n    users: [],                                    # optional\n    targets: [],                                  # optional\n    draft: true,                                  # optional\n    scheduled_at: ''                              # optional\n)\n\nputs response.inspect\n```\n```csharp\nusing Appwrite;\nusing Appwrite.Services;\nusing Appwrite.Models;\n\nvar client = new Client()\n    .SetEndPoint(\"https://<REGION>.cloud.appwrite.io/v1\") // Your API Endpoint\n    .SetProject(\"<PROJECT_ID>\")                  // Your project ID\n    .SetKey(\"919c2d18fb5d4...a2ae413da83346ad2\"); // Your secret API key\n\nvar messaging = new Messaging(client);\n\nMessage result = await messaging.CreateSMS(\n    messageId: \"<MESSAGE_ID>\",\n    content: \"<CONTENT>\"    \n    topics: new List<string> {}                   // optional    \n    users: new List<string> {}                    // optional    \n    targets: new List<string> {}                  // optional    \n    draft: true                                   // optional    \n    scheduledAt: \"\");                             // optional\n```\n```dart\nimport 'package:dart_appwrite/dart_appwrite.dart';\nimport 'package:dart_appwrite/enums.dart';\nimport 'package:dart_appwrite/models.dart';\n\nvoid main() {                                    // Init SDK\n  Client client = Client();\n  Messaging messaging = Messaging(client);\n\n  client\n    .setEndpoint('https://<REGION>.cloud.appwrite.io/v1') // Your API Endpoint\n    .setProject('<PROJECT_ID>')                 // Your project ID\n    .setKey('919c2d18fb5d4...a2ae413da83346ad2') // Your secret API key\n  ;\n\n  Future result = messaging.createSms(\n    messageId: '<MESSAGE_ID>',\n    content: '<CONTENT>',\n    topics: [],                                  // optional\n    users: [],                                   // optional\n    targets: [],                                 // optional\n    draft: true,                                 // optional\n    scheduledAt: '',                             // optional\n  );\n\n  result\n    .then((response) {\n      print(response);\n    }).catchError((error) {\n      print(error.response);\n  });\n}\n```\n```kotlin\nimport io.appwrite.Client;\nimport io.appwrite.coroutines.CoroutineCallback;\nimport io.appwrite.services.Messaging;\n\nClient client = new Client()\n    .setEndpoint(\"https://<REGION>.cloud.appwrite.io/v1\") // Your API Endpoint\n    .setProject(\"<PROJECT_ID>\")                  // Your project ID\n    .setKey(\"919c2d18fb5d4...a2ae413da83346ad2\"); // Your secret API key\n\nMessaging messaging = new Messaging(client);\n\nmessaging.createSms(\n    \"<MESSAGE_ID>\",                               // messageId\n    \"<CONTENT>\",                                  // content\n    listOf(),                                     // topics (optional)\n    listOf(),                                     // users (optional)\n    listOf(),                                     // targets (optional)\n    true,                                         // draft (optional)\n    \"\"                                            // scheduledAt (optional)\n    new CoroutineCallback<>((result, error) -> {\n        if (error != null) {\n            error.printStackTrace();\n            return;\n        }\n\n        System.out.println(result);\n    })\n);\n```\n```java\nimport io.appwrite.Client;\nimport io.appwrite.coroutines.CoroutineCallback;\nimport io.appwrite.services.Messaging;\n\nClient client = new Client()\n    .setEndpoint(\"https://<REGION>.cloud.appwrite.io/v1\") // Your API Endpoint\n    .setProject(\"<PROJECT_ID>\")                  // Your project ID\n    .setKey(\"919c2d18fb5d4...a2ae413da83346ad2\"); // Your secret API key\n\nMessaging messaging = new Messaging(client);\n\nmessaging.createSms(\n    \"<MESSAGE_ID>\",                               // messageId\n    \"<CONTENT>\",                                  // content\n    listOf(),                                     // topics (optional)\n    listOf(),                                     // users (optional)\n    listOf(),                                     // targets (optional)\n    true,                                         // draft (optional)\n    \"\"                                            // scheduledAt (optional)\n    new CoroutineCallback<>((result, error) -> {\n        if (error != null) {\n            error.printStackTrace();\n            return;\n        }\n\n        System.out.println(result);\n    })\n);\n```\n```swift\nimport Appwrite\n\nlet client = Client()\n    .setEndpoint(\"https://<REGION>.cloud.appwrite.io/v1\") // Your API Endpoint\n    .setProject(\"<PROJECT_ID>\")                 // Your project ID\n    .setKey(\"919c2d18fb5d4...a2ae413da83346ad2\") // Your secret API key\n\nlet messaging = Messaging(client)\n\nlet message = try await messaging.createSms(\n  messageId: \"<MESSAGE_ID>\",\n  content: \"<CONTENT>\",\n  topics: [],                                    // optional\n  users: [],                                     // optional\n  targets: [],                                   // optional\n  draft: true,                                   // optional\n  scheduledAt: \"\"                                // optional\n)\n```\n```server-rust\nuse appwrite::Client;\nuse appwrite::services::messaging::Messaging;\n\n#[tokio::main]\nasync fn main() -> Result<(), Box<dyn std::error::Error>> {\n    let client = Client::new()\n        .set_endpoint(\"https://<REGION>.cloud.appwrite.io/v1\")\n        .set_project(\"<PROJECT_ID>\")\n        .set_key(\"919c2d18fb5d4...a2ae413da83346ad2\");\n\n    let messaging = Messaging::new(&client);\n\n    let message = messaging.create_sms(\n        \"<MESSAGE_ID>\",                              // messageId\n        \"<CONTENT>\",                                 // content\n        Some(vec![]),                                // topics (optional)\n        Some(vec![]),                                // users (optional)\n        Some(vec![]),                                // targets (optional)\n        Some(true),                                  // draft (optional)\n        None,                                        // scheduledAt (optional)\n    ).await?;\n\n    println!(\"{:?}\", message);\n    Ok(())\n}\n```\n{% /multicode %}\n{% /tabsitem %}\n{% /tabs %}\n\nYou can follow the [Send SMS messages](/docs/products/messaging/send-sms-messages) guide to send your first push notification and test your provider.\n{% /section %}\n\n{% section #manage-provider step=4 title=\"Manage provider\" %}\n{% tabs %}\n{% tabsitem #console title=\"Console\" %}\nYou can update or delete a provider in the Appwrite Console.\n\nNavigate to **Messaging** > **Providers** > click your provider.\nIn the settings, you can update a provider's configuration or delete the provider.\n{% /tabsitem %}\n\n{% tabsitem #server-sdk title=\"Server SDK\" %}\nTo update or delete providers programmatically, use an [Appwrite Server SDK](/docs/sdks#server).\n{% multicode %}\n```server-nodejs\nconst sdk = require('node-appwrite');\n\n// Init SDK\nconst client = new sdk.Client();\n\nconst messaging = new sdk.Messaging(client);\n\nclient\n    .setEndpoint('https://<REGION>.cloud.appwrite.io/v1') // Your API Endpoint\n    .setProject('<PROJECT_ID>')                 // Your project ID\n    .setKey('919c2d18fb5d4...a2ae413da83346ad2') // Your secret API key\n;\n\nconst provider = await messaging.updateVonageProvider({\n    providerId: '<PROVIDER_ID>',\n    name: '<NAME>',\n    enabled: false,\n    apiKey: '<API_KEY>',\n    apiSecret: '<API_SECRET>',\n    from: '<FROM>'\n});\n```\n```deno\nimport * as sdk from \"npm:node-appwrite\";\n\n// Init SDK\nlet client = new sdk.Client();\n\nlet messaging = new sdk.Messaging(client);\n\nclient\n    .setEndpoint('https://<REGION>.cloud.appwrite.io/v1') // Your API Endpoint\n    .setProject('<PROJECT_ID>')                 // Your project ID\n    .setKey('919c2d18fb5d4...a2ae413da83346ad2') // Your secret API key\n;\n\nconst provider = await messaging.updateVonageProvider({\n    providerId: '<PROVIDER_ID>',\n    name: '<NAME>',\n    enabled: false,\n    apiKey: '<API_KEY>',\n    apiSecret: '<API_SECRET>',\n    from: '<FROM>'\n});\n```\n```php\n<?php\n\nuse Appwrite\\Client;\nuse Appwrite\\Services\\Messaging;\n\n$client = new Client();\n\n$client\n    ->setEndpoint('https://<REGION>.cloud.appwrite.io/v1') // Your API Endpoint\n    ->setProject('<PROJECT_ID>')                 // Your project ID\n    ->setKey('919c2d18fb5d4...a2ae413da83346ad2') // Your secret API key\n;\n\n$messaging = new Messaging($client);\n\n$result = $messaging->updateVonageProvider(\n    providerId: '<PROVIDER_ID>',\n    name: '<NAME>',                               // optional\n    enabled: false,                               // optional\n    apiKey: '<API_KEY>',                          // optional\n    apiSecret: '<API_SECRET>',                    // optional\n    from: '<FROM>'                                // optional\n);\n```\n```python\nfrom appwrite.client import Client\nfrom appwrite.services.messaging import Messaging\n\nclient = Client()\n\n(client\n  .set_endpoint('https://<REGION>.cloud.appwrite.io/v1') # Your API Endpoint\n  .set_project('<PROJECT_ID>')                 # Your project ID\n  .set_key('919c2d18fb5d4...a2ae413da83346ad2') # Your secret API key\n)\n\nmessaging = Messaging(client)\n\nresult = messaging.update_vonage_provider(\n    provider_id = '<PROVIDER_ID>',\n    name = '<NAME>',                            # optional\n    enabled = False,                            # optional\n    api_key = '<API_KEY>',                      # optional\n    api_secret = '<API_SECRET>',                # optional\n    from = '<FROM>'                             # optional\n)\n```\n```ruby\nrequire 'appwrite'\n\ninclude Appwrite\n\nclient = Client.new\n    .set_endpoint('https://<REGION>.cloud.appwrite.io/v1') # Your API Endpoint\n    .set_project('<PROJECT_ID>')                 # Your project ID\n    .set_key('919c2d18fb5d4...a2ae413da83346ad2') # Your secret API key\n\nmessaging = Messaging.new(client)\n\nresponse = messaging.update_vonage_provider(\n    provider_id: '<PROVIDER_ID>',\n    name: '<NAME>',                               # optional\n    enabled: false,                               # optional\n    api_key: '<API_KEY>',                         # optional\n    api_secret: '<API_SECRET>',                   # optional\n    from: '<FROM>'                                # optional\n)\n\nputs response.inspect\n```\n```csharp\nusing Appwrite;\nusing Appwrite.Services;\nusing Appwrite.Models;\n\nvar client = new Client()\n    .SetEndPoint(\"https://<REGION>.cloud.appwrite.io/v1\") // Your API Endpoint\n    .SetProject(\"<PROJECT_ID>\")                  // Your project ID\n    .SetKey(\"919c2d18fb5d4...a2ae413da83346ad2\"); // Your secret API key\n\nvar messaging = new Messaging(client);\n\nProvider result = await messaging.UpdateVonageProvider(\n    providerId: \"<PROVIDER_ID>\"\n    name: \"<NAME>\"                                // optional\n    enabled: false                                // optional\n    apiKey: \"<API_KEY>\"                           // optional\n    apiSecret: \"<API_SECRET>\"                     // optional\n    from: \"<FROM>\");                              // optional\n```\n```dart\nimport 'package:dart_appwrite/dart_appwrite.dart';\nimport 'package:dart_appwrite/enums.dart';\nimport 'package:dart_appwrite/models.dart';\n\nvoid main() {                                    // Init SDK\n  Client client = Client();\n  Messaging messaging = Messaging(client);\n\n  client\n    .setEndpoint('https://<REGION>.cloud.appwrite.io/v1') // Your API Endpoint\n    .setProject('<PROJECT_ID>')                 // Your project ID\n    .setKey('919c2d18fb5d4...a2ae413da83346ad2') // Your secret API key\n  ;\n\n  Future result = messaging.updateVonageProvider(\n    providerId: '<PROVIDER_ID>',\n    name: '<NAME>',                              // optional\n    enabled: false,                              // optional\n    apiKey: '<API_KEY>',                         // optional\n    apiSecret: '<API_SECRET>',                   // optional\n    from: '<FROM>',                              // optional\n  );\n\n  result\n    .then((response) {\n      print(response);\n    }).catchError((error) {\n      print(error.response);\n  });\n}\n```\n```kotlin\nimport io.appwrite.Client;\nimport io.appwrite.coroutines.CoroutineCallback;\nimport io.appwrite.services.Messaging;\n\nClient client = new Client()\n    .setEndpoint(\"https://<REGION>.cloud.appwrite.io/v1\") // Your API Endpoint\n    .setProject(\"<PROJECT_ID>\")                  // Your project ID\n    .setKey(\"919c2d18fb5d4...a2ae413da83346ad2\"); // Your secret API key\n\nMessaging messaging = new Messaging(client);\n\nmessaging.updateVonageProvider(\n    \"<PROVIDER_ID>\",                              // providerId\n    \"<NAME>\",                                     // name (optional)\n    false,                                        // enabled (optional)\n    \"<API_KEY>\",                                  // apiKey (optional)\n    \"<API_SECRET>\",                               // apiSecret (optional)\n    \"<FROM>\"                                      // from (optional)\n    new CoroutineCallback<>((result, error) -> {\n        if (error != null) {\n            error.printStackTrace();\n            return;\n        }\n\n        System.out.println(result);\n    })\n);\n```\n```java\nimport io.appwrite.Client;\nimport io.appwrite.coroutines.CoroutineCallback;\nimport io.appwrite.services.Messaging;\n\nClient client = new Client()\n    .setEndpoint(\"https://<REGION>.cloud.appwrite.io/v1\") // Your API Endpoint\n    .setProject(\"<PROJECT_ID>\")                  // Your project ID\n    .setKey(\"919c2d18fb5d4...a2ae413da83346ad2\"); // Your secret API key\n\nMessaging messaging = new Messaging(client);\n\nmessaging.updateVonageProvider(\n    \"<PROVIDER_ID>\",                              // providerId\n    \"<NAME>\",                                     // name (optional)\n    false,                                        // enabled (optional)\n    \"<API_KEY>\",                                  // apiKey (optional)\n    \"<API_SECRET>\",                               // apiSecret (optional)\n    \"<FROM>\"                                      // from (optional)\n    new CoroutineCallback<>((result, error) -> {\n        if (error != null) {\n            error.printStackTrace();\n            return;\n        }\n\n        System.out.println(result);\n    })\n);\n```\n```swift\nimport Appwrite\n\nlet client = Client()\n    .setEndpoint(\"https://<REGION>.cloud.appwrite.io/v1\") // Your API Endpoint\n    .setProject(\"<PROJECT_ID>\")                 // Your project ID\n    .setKey(\"919c2d18fb5d4...a2ae413da83346ad2\") // Your secret API key\n\nlet messaging = Messaging(client)\n\nlet provider = try await messaging.updateVonageProvider(\n  providerId: \"<PROVIDER_ID>\",\n  name: \"<NAME>\",                                // optional\n  enabled: xfalse,                               // optional\n  apiKey: \"<API_KEY>\",                           // optional\n  apiSecret: \"<API_SECRET>\",                     // optional\n  from: \"<FROM>\"                                 // optional\n)\n```\n```server-rust\nuse appwrite::Client;\nuse appwrite::services::messaging::Messaging;\n\n#[tokio::main]\nasync fn main() -> Result<(), Box<dyn std::error::Error>> {\n    let client = Client::new()\n        .set_endpoint(\"https://<REGION>.cloud.appwrite.io/v1\")\n        .set_project(\"<PROJECT_ID>\")\n        .set_key(\"919c2d18fb5d4...a2ae413da83346ad2\");\n\n    let messaging = Messaging::new(&client);\n\n    let provider = messaging.update_vonage_provider(\n        \"<PROVIDER_ID>\",                             // providerId\n        Some(\"<NAME>\"),                              // name (optional)\n        Some(false),                                 // enabled (optional)\n        Some(\"<API_KEY>\"),                           // apiKey (optional)\n        Some(\"<API_SECRET>\"),                        // apiSecret (optional)\n        Some(\"<FROM>\"),                              // from (optional)\n    ).await?;\n\n    println!(\"{:?}\", provider);\n    Ok(())\n}\n```\n{% /multicode %}\n{% /tabsitem %}\n{% /tabs %}\n{% /section %}";
